import java.util.*;

class Solution {
  private final List<Integer> extra = new ArrayList<>();
  private final List<Integer> empty = new ArrayList<>();
  private int best = Integer.MAX_VALUE;

  public int minimumMoves(int[][] grid) {
    for (int r = 0; r < 3; r++)
      for (int c = 0; c < 3; c++) {
        if (grid[r][c] > 1) for (int t = 1; t < grid[r][c]; t++) extra.add(r * 3 + c);
        else if (grid[r][c] == 0) empty.add(r * 3 + c);
      }
    dfs(0, 0, new boolean[empty.size()]);
    return best;
  }

  private void dfs(int i, int cost, boolean[] used) {
    if (cost >= best) return;
    if (i == extra.size()) {
      best = cost;
      return;
    }
    for (int j = 0; j < empty.size(); j++)
      if (!used[j]) {
        used[j] = true;
        int a = extra.get(i), b = empty.get(j);
        dfs(i + 1, cost + Math.abs(a / 3 - b / 3) + Math.abs(a % 3 - b % 3), used);
        used[j] = false;
      }
  }
}
